void main(){test('thirty-two pictogram batches cover complete 398-item catalog',(){final full=<Set<String>>[codeFoodPictogramIds,codeFoodPictogramBatch2Ids,codeFoodPictogramBatch3Ids,codeFoodPictogramBatch4Ids,codeFoodPictogramBatch5Ids,codeFoodPictogramBatch6Ids,codeFoodPictogramBatch7Ids,codeFoodPictogramBatch8Ids,codeFoodPictogramBatch9Ids,codeFoodPictogramBatch10Ids,codeFoodPictogramBatch11Ids,codeFoodPictogramBatch12Ids,codeFoodPictogramBatch13Ids,codeFoodPictogramBatch15Ids];for(final b in full){expect(b.length,24);}final batches=<Set<String>>[...full,codeFoodPictogramBatch14Ids,codeFoodPictogramBatch16Ids,codeFoodPictogramBatch17Ids,codeFoodPictogramBatch18Ids,codeFoodPictogramBatch19Ids,codeFoodPictogramBatch20Ids,codeFoodPictogramBatch21Ids,codeFoodPictogramBatch22Ids,codeFoodPictogramBatch23Ids,codeFoodPictogramBatch24Ids,codeFoodPictogramBatch25Ids,codeFoodPictogramBatch26Ids,codeFoodPictogramBatch27Ids,codeFoodPictogramBatch28Ids,codeFoodPictogramBatch29Ids,codeFoodPictogramBatch30Ids,codeFoodPictogramBatch31Ids,codeFoodPictogramBatch32Ids];for(var i=0;i<batches.length;i++){for(var j=i+1;j<batches.length;j++){expect(batches[i].intersection(batches[j]),isEmpty);}}final union=batches.expand((b)=>b).toSet();expect(union.length,398);expect(union,mealFoodCatalog.map((e)=>e.id).toSet());});}
